INSERT INTO lessons VALUES('P3A-U04-L3',2,'action-course-wording-v2',3,'A',4,'图书角的安静动作','{"id":"P3A-U04-L3","unitId":"P3A-U04","grade":3,"term":"A","unitNumber":4,"unitLesson":3,"order":15,"title":"图书角的安静动作","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"action-course-wording-v2","unitTitle":"忙碌的现在","cards":[{"title":"图书角的安静动作","rule":"这些情景说此刻正在进行的动作，用am/is/are加动词-ing。I配am，单数人物配is，you/we/they及复数人物配are；-ing拼写需按具体词核对，不把双写套到所有词。","example":"Eva is planting seeds beside a wall.","translation":"Eva正在墙边种种子。"},{"title":"图书角的安静动作","rule":"这些情景说此刻正在进行的动作，用am/is/are加动词-ing。I配am，单数人物配is，you/we/they及复数人物配are；-ing拼写需按具体词核对，不把双写套到所有词。","example":"Our friends are polishing a model plane.","translation":"朋友们正在擦一架模型飞机。"},{"title":"图书角的安静动作","rule":"这些情景说此刻正在进行的动作，用am/is/are加动词-ing。I配am，单数人物配is，you/we/they及复数人物配are；-ing拼写需按具体词核对，不把双写套到所有词。","example":"I am hanging a paper lantern.","translation":"我正在挂一盏纸灯笼。"}],"vocabulary":[{"word":"carry","meaning":"搬、提"},{"word":"rope","meaning":"绳子"},{"word":"glue","meaning":"胶水"},{"word":"borrow","meaning":"借入"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.present-continuous","forms.ing"],"itemCount":9,"version":2}');
INSERT INTO items VALUES('P3A-U04-L3.p3.choice',2,'P3A-U04-L3',2,'grammar.present-continuous','recognition','choice','{"title":"图书角的安静动作","gradeMin":3,"id":"P3A-U04-L3.p3.choice","type":"choice","category":"grammar","context":"此刻两个男孩正在找一本字典。","prompt":"The boys ___ looking for a dictionary now.","choices":["are","is","am"]}','{"answers":["are"],"family":"fact-0bd5db70520deeaa","hint":"这些情景说此刻正在进行的动作，用am/is/are加动词-ing。I配am，单数人物配is，you/we/they及复数人物配are；-ing拼写需按具体词核对，不把双写套到所有词。","explanation":"The boys are looking for a dictionary now. 此刻两个男孩正在找一本字典。 这些情景说此刻正在进行的动作，用am/is/are加动词-ing。I配am，单数人物配is，you/we/they及复数人物配are；-ing拼写需按具体词核对，不把双写套到所有词。","solutionSentences":["The boys are looking for a dictionary now."]}','published');
